<template><div class="print-page"><div class="toolbar no-print"><el-button @click="router.back()">返回</el-button><el-button type="primary" icon="Printer" @click="print">打印</el-button></div><A4Canvas v-if="info" :padding-mm="15"><PrintCompanyHeader variant="center"/><h1>收 款 单</h1><div class="info"><div>单号：{{info.receiptNo}}</div><div>日期：{{info.receiptDate||'-'}}</div><div>客户：{{info.customerName||'-'}}</div><div>关联发票：{{info.invoiceId||'-'}}</div><div>关联订单：{{info.orderId||'-'}}</div><div>收款方式：{{SalesReceiptPaymentMethodEnum.getLabel(info.paymentMethod!)}}</div><div>币种：{{info.currency||'CNY'}}</div></div><table><tbody><tr><th>应收金额</th><td>{{money(info.receiptAmount)}}</td><th>实收金额</th><td>{{money(info.actualAmount)}}</td></tr><tr><th>备注</th><td colspan="3">{{info.remark||'-'}}</td></tr></tbody></table><div class="sign"><span>收款人：________________</span><span>客户确认：________________</span></div></A4Canvas></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import A4Canvas from '@/components/A4Canvas/index.vue';import PrintCompanyHeader from '@/components/PrintCompanyHeader.vue';import{salesReceiptApi,type SalesReceipt}from'@/api/sales/receipt';import{SalesReceiptPaymentMethodEnum}from'@/enums/sales';const route=useRoute(),router=useRouter(),info=ref<SalesReceipt>();const money=(v?:number)=>v==null?'-':Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2});async function print(){if(!info.value)return;try{await salesReceiptApi.printLog(info.value.receiptId);window.print()}catch{ElMessage.error('打印留痕失败，请重试')}}onMounted(async()=>{const r:any=await salesReceiptApi.detail(Number(route.params.id));info.value=r.data})</script>
<style scoped>.print-page{min-height:100vh;background:#eef0f3;padding:20px}.toolbar{max-width:794px;margin:0 auto 16px;display:flex;justify-content:space-between}h1{text-align:center;font-size:20px;letter-spacing:10px;border-bottom:2px solid #2b5aa7;padding-bottom:10px}.info{display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:12px;margin:16px 0}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border:1px solid #bbb;padding:10px}th{background:#eef3fa}.sign{display:flex;justify-content:space-between;margin-top:70px;font-size:12px}@media print{.print-page{padding:0;background:white}}</style>
